            sys.stderr.write("Error: .git directory not found\n")
            return 2
        hook = os.path.join(gitdir, 'hooks', 'pre-commit')
        try:
            with open(hook, 'a', encoding='utf-8') as f:
                f.write(HOOK_LINE)
        except OSError as e:
            sys.stderr.write(f"Error: {e.strerror} (os error {e.errno})\n")
            return 2
    return 0


def load_ignore():
    path_patterns = []
    secret_values = set()
    try:
        with open('.secretsignore', 'rb') as f:
            raw_lines = f.read().splitlines()
    except OSError:
        return path_patterns, secret_values
    mode = 'files'
    for raw in raw_lines:
        line = raw.decode('latin-1')
        # splitlines removes LF and CRLF; a bare CR is considered part by Rust, but rare.
        s = line.strip()
        if not s or s.startswith('#'):
            continue
        if s.startswith('[') and s.endswith(']'):
            mode = 'secrets' if s.lower() == '[secrets]' else 'files'
            continue
        if mode == 'secrets':
            secret_values.add(s.encode('latin-1'))
        else:
            path_patterns.append(s)
    return path_patterns, secret_values


def rel_for_ignore(path):
    try:
        r = os.path.relpath(path, os.getcwd())
    except ValueError:
        r = path
    return r.replace(os.sep, '/')


def pattern_matches(pat, rel, is_dir=False):
    rel = rel.lstrip('./') if rel.startswith('./') else rel
    pat0 = pat
    if pat0.startswith('!'):
        # ripsecrets' ignore file does not appear to implement gitignore negation.
        return False
    anchored = pat0.startswith('/')
    if anchored:
        pat0 = pat0[1:]
    dirpat = pat0.endswith('/')
    if dirpat:
        pat0 = pat0.rstrip('/')
    if not pat0:
        return False
    if dirpat:
        if anchored or '/' in pat0:
            return rel == pat0 or rel.startswith(pat0 + '/')
        parts = rel.split('/')
        return pat0 in parts
    if '/' in pat0 or anchored:
        return fnmatch.fnmatchcase(rel, pat0)
    return any(fnmatch.fnmatchcase(part, pat0) for part in rel.split('/'))


def is_ignored_path(path, patterns, is_dir=False):
    rel = rel_for_ignore(path)
    return any(pattern_matches(p, rel, is_dir=is_dir) for p in patterns)


