    parts = [p for p in rel.replace(os.sep, '/').split('/') if p and p != '.']
    return any(p.startswith('.') for p in parts)


def entropy(bs):
    if not bs:
        return 0.0
    counts = {}
    for b in bs:
        counts[b] = counts.get(b, 0) + 1
    n = len(bs)
    return -sum((c/n) * math.log2(c/n) for c in counts.values())


def repeated_pattern(s):
    n = len(s)
    if n < 6:
        return False
    # Reject exact short-period repetitions, and near-repetitions such as ABCDEFABCDEFABCD.
    for p in range(1, min(7, n // 2 + 1)):
        unit = s[:p]
        built = (unit * ((n + p - 1) // p))[:n]
        if built == s:
            return True
    return False


def randomish(bs):
    if not bs:
        return False
    s = bs.decode('latin-1', 'ignore')
    if len(set(s)) <= 1:
        return False
    if repeated_pattern(s):
        return False
    low = s.lower()
    if low in {'password', 'passwd', 'secret', 'token', 'apikey', 'api_key', 'correcthorsebatterystaple'}:
        return False
    if s.isdigit() and len(s) < 10:
        return False
    # Long, natural-looking all-lowercase words and alphabet runs are common false positives.
    if len(s) >= 8 and all(('a' <= ch <= 'z') or ch in '-_' for ch in s):
        return False
    if s in {'ABCDEFGH', 'ABCDEFGHIJKLMNOPQRSTUVWXYZ'[:len(s)]} and len(s) < 16:
        return False
    h = entropy(bs)
    if len(s) <= 3:
        return len(set(s)) >= 3 and not s.isdigit()
    if len(s) < 8:
        return h >= 1.45 and not (s.isdigit())
    return h >= 2.45


