    alts = list(BASE_ALTS)
    for p in additional:
        alts.append(p.encode('latin-1'))
    # The original combines alternatives inside one outer capture; nested captures are
    # used for the actual secret when present.
    return re.compile(br"(" + br"|".join(alts) + br")")


def selected_capture(m):
    # Skip the outer capture group. Return (value, has_inner_capture).
    groups = m.groups()
    for g in groups[1:]:
        if g is not None and len(g) > 0:
            return g, True
    return m.group(0), False


def accepted_matches(line, regex, ignored_secrets):
    out = []
    for m in regex.finditer(line):
        val, inner = selected_capture(m)
        if val in ignored_secrets:
            continue
        if inner and not randomish(val):
            continue
        out.append(val)
    return out


def scan_file(path, display, regex, ignored_secrets, only_matching):
    found = False
    try:
        with open(path, 'rb') as f:
            data = f.read()
    except OSError as e:
        sys.stderr.write(f"{display}: {e.strerror} (os error {e.errno})\n")
        return False
    lines = data.split(b'\n')
    if lines and lines[-1] == b'':
        lines = lines[:-1]
    disp_b = display.encode('utf-8', 'surrogateescape')
    for idx, line in enumerate(lines, 1):
        matches = accepted_matches(line, regex, ignored_secrets)
        if not matches:
            continue
        found = True
        if only_matching:
            for val in matches:
                sys.stdout.buffer.write(disp_b + b':' + str(idx).encode() + b':' + val + b'\n')
        else:
            sys.stdout.buffer.write(disp_b + b':' + str(idx).encode() + b':' + line + b'\n')
    return found


def iter_files_for_source(src, patterns, strict):
    # Returns (real_path, display_path). Missing/read errors are yielded as errors by caller where possible.
    if src == '-':
        return []
    if not os.path.exists(src):
        sys.stderr.write(f"{src}: No such file or directory (os error 2)\n")
        return []
    isdir = os.path.isdir(src)
    top_ignored = is_ignored_path(src, patterns, is_dir=isdir)
    if top_ignored and strict:
        return []
    bypass_top_ignore = top_ignored and not strict

    def hidden_skip(path, base_explicit):
        if base_explicit:
            return False
        rel = os.path.relpath(path, src if isdir else os.path.dirname(src) or '.')
        return has_hidden_component(rel)

    if os.path.isfile(src):
        if (not bypass_top_ignore) and is_ignored_path(src, patterns, is_dir=False) and strict:
            return []
        if top_ignored and strict:
            return []
        return [(src, src)]
    if not isdir:
        return []
    results = []
    # Explicit hidden or .git source is scanned; otherwise skip hidden children.
    explicit_hidden_root = os.path.basename(os.path.normpath(src)).startswith('.')
    for root, dirs, files in os.walk(src, followlinks=True):
        # Access errors in os.walk are not surfaced unless onerror is used; do an explicit listdir check.
        relroot_from_src = os.path.relpath(root, src)
        root_is_top = relroot_from_src == '.'
        keep_dirs = []
        for d in dirs:
            p = os.path.join(root, d)
            child_rel = os.path.relpath(p, src)
            if not explicit_hidden_root and d.startswith('.'):
                continue
            if not bypass_top_ignore and is_ignored_path(p, patterns, is_dir=True):
                continue
            keep_dirs.append(d)
        # Keep platform order rather than sorting; this is closest to the parallel walker on many simple cases.
        dirs[:] = keep_dirs
        for name in files:
            p = os.path.join(root, name)
            if not explicit_hidden_root and name.startswith('.'):
                continue
            if not bypass_top_ignore and is_ignored_path(p, patterns, is_dir=False):
                continue
            display = os.path.join(src, os.path.relpath(p, src))
            if src == '.':
                display = './' + os.path.relpath(p, src)
            results.append((p, display))
    return results


def scan(opts):
    try:
        regex = build_regex(opts['additional'])
    except re.error as e:
        sys.stderr.write(f"Error: regex parse error: {e}\n")
        return 2
    patterns, ignored_secrets = load_ignore()
    sources = opts['sources'] or ['.']
    any_found = False
    for src in sources:
        for path, display in iter_files_for_source(src, patterns, opts['strict']):
            if scan_file(path, display, regex, ignored_secrets, opts['only']):
                any_found = True
    return 1 if any_found else 0


def main():
    opts = parse_args(sys.argv[1:])
    if opts['install']:
        return install_pre_commit(opts['sources'])
    return scan(opts)

if __name__ == '__main__':
    try:
        raise SystemExit(main())
    except BrokenPipeError:
        raise SystemExit(1)
